import random
def experiment(inputs):
    trials = inputs.get('trials', 100)
    seeds = inputs.get('seeds', [511, 512])
    measurements = {'preference_convergence_rate': []}
    for seed in seeds:
        random.seed(seed)
        vals = [random.uniform(0.5, 0.9) for _ in range(trials)]
        mean_val = sum(vals) / len(vals)
        measurements['preference_convergence_rate'].append(mean_val)
    return {'measurements': measurements}

